-- Scaling rules (upsert by name)
CREATE TABLE IF NOT EXISTS scaling_rules (
  id           SERIAL PRIMARY KEY,
  name         TEXT UNIQUE NOT NULL,
  dice_count   SMALLINT NOT NULL DEFAULT 1,
  dice_size    SMALLINT NOT NULL,
  every_levels SMALLINT NOT NULL,
  start_level  SMALLINT NOT NULL DEFAULT 1,
  description  TEXT
);

INSERT INTO scaling_rules (name, dice_count, dice_size, every_levels, start_level, description) VALUES
  ('Cantrip d8', 1, 8, 5, 5, 'Adds 1d8 every 5 levels starting at level 5 (L5, 10, 15, 20).'),
  ('Cantrip d10', 1, 10, 5, 5, 'Adds 1d10 every 5 levels starting at level 5.'),
  ('Cantrip d12', 1, 12, 5, 5, 'Adds 1d12 every 5 levels starting at level 5.'),
  ('Strike d6 every 3', 1, 6, 3, 3, 'Adds 1d6 every 3 levels starting at level 3.'),
  ('Strike d6 every 4', 1, 6, 4, 5, 'Adds 1d6 every 4 levels starting at level 5.'),
  ('Strike d8 every 4', 1, 8, 4, 5, 'Adds 1d8 every 4 levels starting at level 5.'),
  ('Brand d6 every 5', 1, 6, 5, 5, 'Adds 1d6 every 5 levels starting at level 5 (marks, smites, brands).'),
  ('Brand d8 every 5', 1, 8, 5, 5, 'Adds 1d8 every 5 levels starting at level 5.'),
  ('Healing d4 every 3', 1, 4, 3, 3, 'Restores 1d4 more every 3 levels starting at level 3.'),
  ('Healing d8 every 5', 1, 8, 5, 5, 'Restores 1d8 more every 5 levels starting at level 5.'),
  ('Healing 2d8 every 10', 2, 8, 10, 10, 'Restores 2d8 more every 10 levels starting at level 10.'),
  ('Burst 2d6 every 5', 2, 6, 5, 5, 'Adds 2d6 every 5 levels starting at level 5.'),
  ('Burst 2d8 every 6', 2, 8, 6, 6, 'Adds 2d8 every 6 levels starting at level 6.'),
  ('Ongoing d4 every 5', 1, 4, 5, 5, 'Ongoing or aura damage adds 1d4 every 5 levels starting at level 5.'),
  ('Ongoing d6 every 5', 1, 6, 5, 5, 'Ongoing or aura damage adds 1d6 every 5 levels starting at level 5.'),
  ('Ward d6 every 4', 1, 6, 4, 4, 'Ward or temporary hit points add 1d6 every 4 levels starting at level 4.'),
  ('Ward d10 every 5', 1, 10, 5, 5, 'Ward or temporary hit points add 1d10 every 5 levels starting at level 5.'),
  ('Flat +1 every 4', 1, 1, 4, 4, 'Adds +1 every 4 levels starting at level 4.'),
  ('Flat +1 every 5', 1, 1, 5, 5, 'Adds +1 every 5 levels starting at level 5.'),
  ('Flat +1 every 10', 1, 1, 10, 10, 'Adds +1 every 10 levels starting at level 10.'),
  ('1d4 every 4 from 2', 1, 4, 4, 2, 'Adds 1d4 every 4 levels starting at level 2.'),
  ('1d6 every 4 from 3', 1, 6, 4, 3, 'Adds 1d6 every 4 levels starting at level 3.'),
  ('Sneak d6 every 2', 1, 6, 2, 1, 'Adds 1d6 every 2 levels starting at level 1 (Hidden Blade style).')
ON CONFLICT (name) DO UPDATE SET
  dice_count = EXCLUDED.dice_count,
  dice_size = EXCLUDED.dice_size,
  every_levels = EXCLUDED.every_levels,
  start_level = EXCLUDED.start_level,
  description = EXCLUDED.description;

