-- Update features.description, type, and merge rules into features.data
UPDATE features f SET
  description = v.description,
  type = v.type,
  data = COALESCE(f.data, '{}'::jsonb) || v.rules
FROM (VALUES
  ('aegis', 'Bonus action: one creature within 30 feet gains +2 AC for 1 minute. Uses = proficiency bonus per long rest.', 'bonus', '{"action_type":"bonus","uses":"proficiency bonus","recharge":"long_rest","dice":null,"save":null,"range":"30 ft","duration":"1 minute","scaling":[],"status":"PROPOSED"}'::jsonb),
  ('allegiance', 'Action: one creature within 60 feet makes a Judgment roll vs your Intellect DC. On a failure it is controlled by you (ally to you) for 1 minute. It repeats the Judgment roll at the end of each of its turns; on a success the effect ends. Once per long rest. Does not work on creatures with legendary resistance-style daily auto-successes unless the Guide allows. Allegiance targets are not summons: they cannot receive Forced Command, do not count against your Legion cap, and only follow simple commands (Attack, Dash, Disengage, Dodge, or drop an item).', 'action', '{"action_type":"action","uses":1,"recharge":"long_rest","dice":null,"save":{"stat":"Judgment","dc":"8 + proficiency bonus + Judgment"},"range":"60 ft","duration":"1 minute","scaling":[],"key_stat":"Intellect","forced_command_eligible":false,"counts_as_summon":false,"status":"PROPOSED"}'::jsonb),
  ('alpha', 'Once per long rest as a bonus action, for 1 minute hybrid form has Extra Attack (two natural attacks), Primal Strikes +2d6, and Pack Leader aura 30 feet.', 'bonus', '{"action_type":"bonus","uses":1,"recharge":"long_rest","dice":"2d6","save":null,"range":null,"duration":"1 minute","scaling":[],"attacks":2,"status":"PROPOSED"}'::jsonb),
  ('ancient_willow', 'Once per long rest, when an ally within 30 feet would drop to 0 HP, they drop to 1 HP and gain temporary HP equal to your Templar level + Judgment.', 'reaction', '{"action_type":"reaction","uses":1,"recharge":"long_rest","dice":"Templar level+Judgment","save":null,"range":"30 ft","duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('angelic_decree', 'Action: each enemy of your choice within 30 feet makes a Judgment roll vs your Judgment DC or is frightened until the end of your next turn. Once per short rest.', 'action', '{"action_type":"action","uses":1,"recharge":"short_rest","dice":null,"save":{"stat":"Judgment","dc":"8 + proficiency bonus + Judgment"},"range":"30 ft","duration":"until end of your next turn","scaling":[],"key_stat":"Judgment","status":"PROPOSED"}'::jsonb),
  ('animal_ally', 'You gain a beast companion (CR 1/4 or lower). It acts on your turn; you command it as a bonus action. If it dies, ritual 8 hours to bond another.', 'bonus', '{"action_type":"bonus","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('anthem', 'Action: allies within 30 feet gain +2 to attacks and damage for 1 minute. Once per long rest.', 'action', '{"action_type":"action","uses":1,"recharge":"long_rest","dice":null,"save":null,"range":"30 ft","duration":"1 minute","scaling":[],"status":"PROPOSED"}'::jsonb),
  ('arcane_ambush', 'When you cast an Assassin spell of 1st rank+ while hidden, the target has disadvantage on rolls against its DC, or you have advantage on the spell attack.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('archmage', 'Once per long rest when you cast a Mage spell of 1st rank+, treat it as if cast using a slot one rank higher (max 9th). You also regain one expended 1st- or 2nd-rank slot at the start of each of your turns in combat while you have none of those ranks left (once per turn).', 'free', '{"action_type":"free","uses":1,"recharge":"long_rest","dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('armor_crack', 'When you hit the same creature twice in a turn, its AC is reduced by 1 until the start of your next turn (stacks to -3).', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":"until start of next turn","scaling":[],"status":"PROPOSED"}'::jsonb),
  ('assemble_construct', 'Legion can call constructs (armor +1 AC, immunity to poison and psychic). Constructs can be repaired with Scrap Field Repair.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('augment', 'Spend 1 Soul as a free action when you hit to add 2d6 fire or necrotic (devil''s choice when bound).', 'free', '{"action_type":"free","uses":null,"recharge":null,"dice":"2d6","save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('avatar_of_the_element', 'Once per long rest as a bonus action, for 1 minute you gain immunity to your attuned element, your cantrips of that type deal +2d8, and enemies that hit you in melee take 2d8 of that type.', 'bonus', '{"action_type":"bonus","uses":1,"recharge":"long_rest","dice":"2d8","save":null,"range":null,"duration":"1 minute","scaling":[],"status":"PROPOSED"}'::jsonb),
  ('avenger', 'Once per long rest as an action, for 1 minute you know the direction to your mark regardless of distance on the same plane, your speed increases by 20 feet toward it, and critical hits against it deal +4d8 necrotic.', 'action', '{"action_type":"action","uses":1,"recharge":"long_rest","dice":"4d8","save":null,"range":null,"duration":"1 minute","scaling":[],"status":"PROPOSED"}'::jsonb),
  ('bane_strike', 'Once per turn against a studied monster type, +2d6 damage and it cannot regain HP until the start of your next turn.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":"2d6","save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('barbed_hide', 'While furious, creatures that hit you with melee take 1d6 piercing. Scales Ongoing d6 every 5 from 13.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":"1d6","save":null,"range":null,"duration":null,"scaling":[],"scaling_rule":"Ongoing d6 every 5","status":"PROPOSED"}'::jsonb),
  ('battle_scribe', 'Bonus action: activate a prepared combat glyph (blast 2d6 in 10 ft, or shield +2 AC until start of next turn). Uses = proficiency bonus per long rest.', 'bonus', '{"action_type":"bonus","uses":"proficiency bonus","recharge":"long_rest","dice":"2d6","save":null,"range":"10 ft","duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('beast_companion', 'Beast companion CR 1/4+. Commands as bonus action; shares your initiative. Bond ritual 8 hours if slain.', 'bonus', '{"action_type":"bonus","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('beast_shape', 'Action: assume a beast form (CR 1 or lower) for 1 hour. Retain Judgment and HP; use beast stats otherwise. Uses = 2 per short rest.', 'action', '{"action_type":"action","uses":2,"recharge":"short_rest","dice":null,"save":null,"range":null,"duration":"1 hour","scaling":[{"level":9,"change":"CR 2"},{"level":13,"change":"Hybrid Form"},{"level":19,"change":"Alpha forms"}],"status":"PROPOSED"}'::jsonb),
  ('beast_sight', 'Share senses with your companion or a beast within 100 feet for 10 minutes as an action. Once per short rest free; or expend a spell slot of 1st+.', 'action', '{"action_type":"action","uses":1,"recharge":"short_rest","dice":null,"save":null,"range":"100 ft","duration":"10 minutes","scaling":[],"status":"PROPOSED"}'::jsonb),
  ('between_worlds', 'You can see into the ethereal within 30 feet. Attacks against ethereal creatures within reach have no disadvantage from that state.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":"30 ft","duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('binding_sigil', 'Bonus action: mark a creature within 60 feet for 1 minute. Its speed is reduced by 10 feet, and it has disadvantage on the first attack each turn against creatures other than you.', 'bonus', '{"action_type":"bonus","uses":null,"recharge":null,"dice":null,"save":null,"range":"60 ft","duration":"1 minute","scaling":[],"status":"PROPOSED"}'::jsonb),
  ('black_rose_elegy', 'Once per long rest as an action, for 1 minute Thorned Lullaby auto-succeeds once per turn (still costs bonus action), Wilting Note deals 4d6, and frightened enemies take 2d6 psychic at the start of their turns.', 'action', '{"action_type":"action","uses":1,"recharge":"long_rest","dice":"4d6 / 2d6","save":null,"range":null,"duration":"1 minute","scaling":[],"status":"PROPOSED"}'::jsonb),
  ('bleeding_edge', 'Bleed dice become 1d6. Critical hits apply bleed automatically without using the once-per-turn limit.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":"1d6","save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('blight_bolt', 'Cantrip: ranged spell attack 60 feet, 1d10 necrotic; scales Cantrip d10. On hit, target cannot regain HP until the start of your next turn.', 'action', '{"action_type":"action","uses":null,"recharge":null,"dice":"1d10","save":null,"range":"60 ft","duration":null,"scaling":[],"scaling_rule":"Cantrip d10","status":"PROPOSED"}'::jsonb),
  ('blood_bolt', 'Action: spend up to proficiency bonus hit dice; each die deals 1d6 necrotic to a creature within 60 feet (Judgment roll vs Confidence DC halves).', 'action', '{"action_type":"action","uses":null,"recharge":null,"dice":"1d6 per HD","save":{"stat":"Judgment","dc":"8 + proficiency bonus + Judgment"},"range":"60 ft","duration":null,"scaling":[],"key_stat":"Confidence","status":"PROPOSED"}'::jsonb),
  ('blood_debt', 'While Grudge is active, the first time each turn the marked creature damages you, it takes necrotic damage equal to your proficiency bonus.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":"PB necrotic","save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('blood_feast', 'Bonus action while furious: end all bleeds you applied within 60 feet; deal remaining bleed dice as necrotic and regain that much HP. Once per short rest.', 'bonus', '{"action_type":"bonus","uses":1,"recharge":"short_rest","dice":null,"save":null,"range":"60 ft","duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('blood_pact', 'Reaction: ally within 30 feet is hit; you take the damage instead with resistance to it. Once per short rest.', 'reaction', '{"action_type":"reaction","uses":1,"recharge":"short_rest","dice":null,"save":null,"range":"30 ft","duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('bloodied_fury', 'While you are below half HP, +2 to melee damage and advantage on Might rolls.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":"+2","save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('bloodletting', 'When casting a Witch spell of 1st rank+, lose HP equal to slot rank to add 1d8 necrotic to one target (or restore 1d8 for healing spells).', 'free', '{"action_type":"free","uses":null,"recharge":null,"dice":"1d8","save":null,"range":null,"duration":null,"scaling":[{"level":9,"change":"1d10"},{"level":15,"change":"2d8"}],"status":"PROPOSED"}'::jsonb),
  ('bloodlust', 'While furious, when you reduce a creature to 0 HP, you may move up to half speed and make one melee attack (once per turn).', 'free', '{"action_type":"free","uses":null,"recharge":null,"dice":null,"save":null,"range":"half speed","duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('boil_blood', 'Action: a hexed or Crimson-Bound creature within 60 feet takes 4d8 necrotic (Endurance vs Confidence DC halves). Once per short rest.', 'action', '{"action_type":"action","uses":1,"recharge":"short_rest","dice":"4d8","save":{"stat":"Endurance","dc":"8 + proficiency bonus + Endurance"},"range":"60 ft","duration":null,"scaling":[],"scaling_rule":"Burst 2d8 every 6","key_stat":"Confidence","status":"PROPOSED"}'::jsonb),
  ('bone_armor', 'Bonus action: sacrifice an undead summon within 30 feet; you gain temporary HP equal to twice its remaining HP (max 40). Once per short rest.', 'bonus', '{"action_type":"bonus","uses":1,"recharge":"short_rest","dice":null,"save":null,"range":"30 ft","duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('bone_grip', 'While furious, you may dual-wield two-handed melee weapons. When you take the Attack action with one of them, you may make one attack with the other as a bonus action (same dual-wield rhythm as the Assassin: one off-hand attack on the bonus action). The off-hand attack uses the weapon''s normal damage die and your Might modifier.', 'bonus', '{"action_type":"bonus","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"off_hand_attacks":1,"requires":"Fury","status":"PROPOSED"}'::jsonb),
  ('bone_plating', 'While furious, gain temporary HP equal to your Berserker level when you enter Fury, and +1 AC.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":"Berserker level temp HP","save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('borrowed_face', 'Action: alter your appearance (clothing, face, height within 1 foot) for 1 hour. Inspection contests Judgment vs your Confidence. Uses = proficiency bonus per long rest.', 'action', '{"action_type":"action","uses":"proficiency bonus","recharge":"long_rest","dice":null,"save":null,"range":null,"duration":"1 hour","scaling":[],"status":"PROPOSED"}'::jsonb),
  ('borrowed_miracle', 'Once per short rest, cast a 1st- or 2nd-rank Wraith spell without expending a slot.', 'action', '{"action_type":"action","uses":1,"recharge":"short_rest","dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('borrowed_time', 'Reaction: when you or an ally within 30 feet fails a death roll, treat it as a success. Once per short rest.', 'reaction', '{"action_type":"reaction","uses":1,"recharge":"short_rest","dice":null,"save":null,"range":"30 ft","duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('bound_ally', 'When you summon a creature with a Mage spell, add your proficiency bonus to its AC and attack rolls for the duration.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('bound_soul', 'One undead summon can remain active for 24 hours without counting against your Legion cap overnight (still counts in combat encounters). Refresh on long rest.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":"24 hours","scaling":[],"status":"PROPOSED"}'::jsonb),
  ('bounty', 'Bonus action: designate a creature within 60 feet as your Bounty for 1 hour (or until it drops to 0). Add 1d6 damage on weapon attacks against it. One bounty. Bounty(2) improves.', 'bonus', '{"action_type":"bonus","uses":null,"recharge":null,"dice":"1d6","save":null,"range":"60 ft","duration":"1 hour","scaling":[{"level":5,"change":"+1d6"},{"level":8,"change":"Bounty(2): +proficiency to track; damage +1d6 more at 8 from scaling"},{"level":10,"change":"+1d6"},{"level":15,"change":"+1d6"},{"level":20,"change":"+1d6"}],"scaling_rule":"Brand d6 every 5","status":"PROPOSED"}'::jsonb),
  ('breaking_point', 'Once per long rest as a bonus action, for 1 minute Weak Point is permanent on one target, Armor Crack stacks to -5, and Precise Blow applies to every hit against it.', 'bonus', '{"action_type":"bonus","uses":1,"recharge":"long_rest","dice":null,"save":null,"range":null,"duration":"1 minute","scaling":[],"status":"PROPOSED"}'::jsonb),
  ('bulwark', 'While wielding a shield, +1 AC. Reaction: impose disadvantage on an attack against an ally within 5 feet. Uses = proficiency bonus per long rest.', 'reaction', '{"action_type":"reaction","uses":"proficiency bonus","recharge":"long_rest","dice":null,"save":null,"range":"5 ft","duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('burning_chorus', 'When you deal damage with a Songsmith cantrip or spell, add +1d6 fire once per cast.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":"1d6","save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('burning_wings', 'Learn Seraphim Invocations. Bonus action: for 1 minute gain fly speed 30 feet (hover). Uses = proficiency bonus per long rest. While flying, Grace Bolt fire die becomes 1d6.', 'bonus', '{"action_type":"bonus","uses":"proficiency bonus","recharge":"long_rest","dice":null,"save":null,"range":"fly 30","duration":"1 minute","scaling":[],"status":"PROPOSED"}'::jsonb),
  ('call_the_hollow', 'Legion can call Hollow spirits (insubstantial; resistance to nonmagical weapons; vulnerable to radiant). Hollows ignore difficult terrain.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('cantrips', 'You know 2 cantrips from your role''s lists. Cantrip damage follows Cantrip scaling rules.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"cantrips_known":2,"casting_stat":"Confidence","status":"PROPOSED","cantrips":2}'::jsonb),
  ('celestial_seer', 'Once per long rest as an action, for 1 minute gain all three moon phases at once and Starfall recharges on each of your turns (still an action).', 'action', '{"action_type":"action","uses":1,"recharge":"long_rest","dice":null,"save":null,"range":null,"duration":"1 minute","scaling":[],"status":"PROPOSED"}'::jsonb),
  ('chains_of_faith', 'Action: target within 30 feet makes a Might roll vs Judgment DC or is restrained 1 minute (repeats each turn). Once per short rest.', 'action', '{"action_type":"action","uses":1,"recharge":"short_rest","dice":null,"save":{"stat":"Might","dc":"8 + proficiency bonus + Might"},"range":"30 ft","duration":"1 minute","scaling":[],"key_stat":"Judgment","status":"PROPOSED"}'::jsonb),
  ('challenge', 'Bonus action: challenge a creature within 60 feet for 1 minute. It has disadvantage on attacks against others while within 5 feet of you; you have advantage on attacks against it. Uses = Confidence modifier (min 1) per long rest.', 'bonus', '{"action_type":"bonus","uses":"Confidence modifier (min 1)","recharge":"long_rest","dice":null,"save":null,"range":"60 ft","duration":"1 minute","scaling":[],"status":"PROPOSED"}'::jsonb),
  ('charity', 'Action: transfer any number of your temporary HP to allies within 30 feet, or spend a short-rest slot to heal all allies within 30 feet for 2d8 + Intellect. Once per short rest for the slot heal.', 'action', '{"action_type":"action","uses":1,"recharge":"short_rest","dice":"2d8+Intellect","save":null,"range":"30 ft","duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('cleansing_grace', 'When you use Grace, you may also end one poison, disease, or mild curse on the target.', 'bonus', '{"action_type":"bonus","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('cleave', 'When you reduce a creature to 0 HP with a melee attack, make one melee attack against a different creature within reach as part of the same attack (once per turn).', 'free', '{"action_type":"free","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('coil', 'Bonus action: take a coiled stance until you move. Your next spear attack has advantage and deals +1d6; if it hits, you may move 10 feet without provoking.', 'bonus', '{"action_type":"bonus","uses":null,"recharge":null,"dice":"1d6","save":null,"range":"10 ft","duration":null,"scaling":[],"scaling_rule":"Brand d6 every 5","status":"PROPOSED"}'::jsonb),
  ('colossus', 'Once per long rest as a bonus action, for 1 minute grow two sizes (Huge if you started Medium), keep Bone Grip dual-wield (one off-hand great-weapon attack as a bonus action), and Crushing Blow becomes +2d8.', 'bonus', '{"action_type":"bonus","uses":1,"recharge":"long_rest","dice":"2d8","save":null,"range":null,"duration":"1 minute","scaling":[],"status":"PROPOSED"}'::jsonb),
  ('combo_chain', 'When you hit the same creature with three unarmed strikes in one turn, it makes an Endurance roll vs Precision DC or is stunned until the end of your next turn. Once per turn.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":{"stat":"Endurance","dc":"8 + proficiency bonus + Endurance"},"range":null,"duration":null,"scaling":[],"key_stat":"Precision","status":"PROPOSED"}'::jsonb),
  ('conjure_tool', 'Bonus action: create a simple nonmagical object (up to 5 lb) for 1 hour or until dismissed. Proficiency bonus uses per long rest.', 'bonus', '{"action_type":"bonus","uses":"proficiency bonus","recharge":"long_rest","dice":null,"save":null,"range":null,"duration":"1 hour","scaling":[],"status":"PROPOSED"}'::jsonb),
  ('corrupt_spell', 'When you cast a Reaver spell of 1st rank+, you may deal +1d6 necrotic to one target and become lightly corrupted until a short rest (Guide tracks corruption; at 3 stacks disadvantage on Judgment social rolls until long rest).', 'free', '{"action_type":"free","uses":null,"recharge":null,"dice":"1d6","save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('counterpunch', 'Reaction: when missed by a melee attack within reach, make one unarmed strike against the attacker. Uses = Speed modifier (min 1) per long rest.', 'reaction', '{"action_type":"reaction","uses":"Speed modifier (min 1)","recharge":"long_rest","dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('countersong', 'Reaction: when an ally within 60 feet fails a Judgment or Confidence roll against a charm/fear effect, add your Confidence modifier to the result. Uses = proficiency bonus per long rest.', 'reaction', '{"action_type":"reaction","uses":"proficiency bonus","recharge":"long_rest","dice":null,"save":null,"range":"60 ft","duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('coven_rites', 'Learn two Rites. Action: expend a spell slot to enact a known Rite (effects scale with slot rank).', 'action', '{"action_type":"action","uses":"spell slot","recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('crescendo', 'Once per long rest when you cast a Songsmith spell of 1st rank+, treat it as one slot rank higher and Verse die becomes 1d10 for 1 minute.', 'free', '{"action_type":"free","uses":1,"recharge":"long_rest","dice":"1d10","save":null,"range":null,"duration":"1 minute","scaling":[],"status":"PROPOSED"}'::jsonb),
  ('crimson_bind', 'Action: creature within 30 feet makes Endurance roll vs Confidence DC or is restrained 1 minute (repeats roll each turn). You lose 1d6 HP. Once per short rest.', 'action', '{"action_type":"action","uses":1,"recharge":"short_rest","dice":"1d6 self","save":{"stat":"Endurance","dc":"8 + proficiency bonus + Endurance"},"range":"30 ft","duration":"1 minute","scaling":[],"key_stat":"Confidence","status":"PROPOSED"}'::jsonb),
  ('crossroads_gate', 'Action: create a linked pair of gates within 60 feet for 1 minute; any creature entering one exits the other. Once per short rest.', 'action', '{"action_type":"action","uses":1,"recharge":"short_rest","dice":null,"save":null,"range":"60 ft","duration":"1 minute","scaling":[],"status":"PROPOSED"}'::jsonb),
  ('crushing_blow', 'Once per turn while furious and grown or dual-wielding great weapons, a melee hit deals +1d8 and the target makes a Might roll vs your Might DC or is knocked prone.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":"1d8","save":{"stat":"Might","dc":"8 + proficiency bonus + Might"},"range":null,"duration":null,"scaling":[],"key_stat":"Might","status":"PROPOSED"}'::jsonb),
  ('current_step', 'When you Flurry, you may move 10 feet before or between strikes without provoking.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":"10 ft","duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('cutpurses_bane', 'Against humanoids marked as Bounty, weapon attacks deal +1d6 and you have advantage on rolls to detect illusions and disguises.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":"1d6","save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
