  ('moonlit_spells', 'When you cast a Seer spell at night or in moonlight, add +1d4 to one damage or healing roll. In darkness you see 30 feet without penalty.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":"1d4","save":null,"range":"30 ft darkvision-like","duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('mourning_song', 'Action: enemies within 30 feet make Judgment vs Confidence DC or are frightened for 1 minute (repeat each turn). Once per short rest.', 'action', '{"action_type":"action","uses":1,"recharge":"short_rest","dice":null,"save":{"stat":"Judgment","dc":"8 + proficiency bonus + Judgment"},"range":"30 ft","duration":"1 minute","scaling":[],"key_stat":"Confidence","status":"PROPOSED"}'::jsonb),
