  ('night_shroud', 'Bonus action: you and one ally within 30 feet become lightly obscured and ignore disadvantage from darkness for 10 minutes. Once per short rest.', 'bonus', '{"action_type":"bonus","uses":1,"recharge":"short_rest","dice":null,"save":null,"range":"30 ft","duration":"10 minutes","scaling":[],"status":"PROPOSED"}'::jsonb),
