  ('oath_of_night', 'Once per short rest when you hit your mark, deal extra 3d8 necrotic and it cannot regain HP until the start of your next turn.', 'free', '{"action_type":"free","uses":1,"recharge":"short_rest","dice":"3d8","save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('oath_of_steel', 'You are proficient with heavy armor, shields, and martial weapons. As a bonus action, adopt a Guard: +1 AC until the start of your next turn, or +1d4 to one ally''s AC within 5 feet until the start of your next turn.', 'bonus', '{"action_type":"bonus","uses":null,"recharge":null,"dice":"1d4 AC to ally","save":null,"range":"5 ft","duration":"until start of next turn","scaling":[],"status":"PROPOSED"}'::jsonb),
