  ('plague_blade', 'Once per short rest when toxin hits, creatures within 5 feet of the target make Endurance vs Precision DC or also become poisoned for 1 minute.', 'free', '{"action_type":"free","uses":1,"recharge":"short_rest","dice":null,"save":{"stat":"Endurance","dc":"8 + proficiency bonus + Endurance"},"range":"5 ft","duration":null,"scaling":[],"key_stat":"Precision","status":"PROPOSED"}'::jsonb),
