  ('primal_strikes', 'Beast form attacks count as magical. Once per turn +1d6 damage in beast or hybrid form.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":"1d6","save":null,"range":null,"duration":null,"scaling":[],"scaling_rule":"Brand d6 every 5","status":"PROPOSED"}'::jsonb),
