  ('quick_strike', 'Reaction: when a creature enters your reach, make one spear attack. Uses = Precision modifier (min 1) per long rest.', 'reaction', '{"action_type":"reaction","uses":"Precision modifier (min 1)","recharge":"long_rest","dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
