  ('raise_dead', 'When you use Legion with a summoning slot, you may raise a skeleton or zombie profile instead of a standard summon. Undead summons have +1 AC.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
