  ('reapers_toll', 'Once per long rest when you hit with a melee weapon, the target makes an Endurance roll vs Might DC; on a failure it drops to 0 if it has 100 HP or fewer, otherwise (or on success) it takes 10d10 necrotic.', 'free', '{"action_type":"free","uses":1,"recharge":"long_rest","dice":"10d10","save":{"stat":"Endurance","dc":"8 + proficiency bonus + Endurance"},"range":null,"duration":null,"scaling":[],"key_stat":"Might","status":"PROPOSED"}'::jsonb),
  ('reaping_blow', 'Action: one melee attack with advantage; on hit +4d8 and if the target has 50 HP or fewer after the hit it drops to 0. Once per short rest.', 'action', '{"action_type":"action","uses":1,"recharge":"short_rest","dice":"4d8","save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('reaping_swing', 'Once per turn when you hit with a melee weapon, deal an extra 1d8 damage. If the hit drops the target to 0 hit points, regain hit points equal to your Warrior level.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":"1d8","save":null,"range":null,"duration":null,"scaling":[{"level":8,"change":"+1d8"},{"level":13,"change":"+1d8"},{"level":18,"change":"+1d8"}],"scaling_rule":"Brand d8 every 5","status":"PROPOSED"}'::jsonb),
  ('rebirth_hymn', 'Reaction: when an ally within 30 feet is reduced to 0 HP, they drop to 1 HP instead. Once per long rest.', 'reaction', '{"action_type":"reaction","uses":1,"recharge":"long_rest","dice":null,"save":null,"range":"30 ft","duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('reckless_swing', 'On your turn, gain advantage on melee weapon attacks until your next turn; attacks against you have advantage until then.', 'free', '{"action_type":"free","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('redirect', 'When you succeed on a roll against a single-target spell of 3rd rank or lower, you may use your reaction to redirect it to another creature within 30 feet of you (original caster''s roll or your Precision for attack).', 'reaction', '{"action_type":"reaction","uses":null,"recharge":null,"dice":null,"save":null,"range":"30 ft","duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('redirect_flow', 'Reaction: when hit by a melee attack, Speed contest vs attacker''s Might or Precision; on success take half damage and the attacker takes the other half as your element type.', 'reaction', '{"action_type":"reaction","uses":"proficiency bonus","recharge":"long_rest","dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
