  ('retaliate', 'When your Grudge target hits you, reaction: one weapon attack against it.', 'reaction', '{"action_type":"reaction","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('revelation', 'Action: for 10 minutes you see invisible creatures and into the ethereal within 60 feet, and know if a creature within 30 feet is lying (Judgment contest). Once per long rest.', 'action', '{"action_type":"action","uses":1,"recharge":"long_rest","dice":null,"save":null,"range":"60 ft","duration":"10 minutes","scaling":[],"status":"PROPOSED"}'::jsonb),
  ('rewrite_fate', 'Once per long rest as an action, choose one creature within 60 feet (or yourself) and reverse or replace one mechanical outcome that occurred since the start of your last turn. Valid targets include: one damage instance, one condition application or removal, one forced move or teleport, one failed check (reroll it and use the new result), or one social or skill outcome (a persuasion/insight/performance-style contest or check result). Death after a completed death sequence cannot be undone. The Guide may block world-scale or multi-creature events beyond character scale. Range 60 feet.', 'action', '{"action_type":"action","uses":1,"recharge":"long_rest","dice":null,"save":null,"range":"60 ft","duration":"instant","scaling":[],"options":["undo one damage instance","undo or restore one condition","undo one forced move or teleport","reroll one failed check (keep new result)","reverse one social or skill outcome"],"status":"PROPOSED"}'::jsonb),
  ('rooted_guard', 'While you haven''t moved since the start of your turn, allies within 10 feet gain +1 AC and you have advantage on rolls against being moved.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":"10 ft","duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('rot', 'Bonus action: infect a creature within 60 feet for 1 minute; 1d6 necrotic at start of its turns; Endurance vs Confidence DC ends. Once per short rest.', 'bonus', '{"action_type":"bonus","uses":1,"recharge":"short_rest","dice":"1d6","save":{"stat":"Endurance","dc":"8 + proficiency bonus + Endurance"},"range":"60 ft","duration":"1 minute","scaling":[],"scaling_rule":"Ongoing d6 every 5","key_stat":"Confidence","status":"PROPOSED"}'::jsonb),
  ('rotting_word', 'Action: creature within 60 feet makes Endurance vs Confidence DC or takes 4d8 necrotic and is poisoned 1 minute. Once per short rest.', 'action', '{"action_type":"action","uses":1,"recharge":"short_rest","dice":"4d8","save":{"stat":"Endurance","dc":"8 + proficiency bonus + Endurance"},"range":"60 ft","duration":"1 minute","scaling":[],"key_stat":"Confidence","status":"PROPOSED"}'::jsonb),
