  ('sanguine_hunger', 'When a bleeding creature within 30 feet takes bleed damage, you regain HP equal to half the bleed damage (rounded up).', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":"30 ft","duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
