  ('scrap_field_repair', 'Bonus action: one construct within 30 feet regains 1d8 + Intellect HP. Uses = proficiency bonus per long rest.', 'bonus', '{"action_type":"bonus","uses":"proficiency bonus","recharge":"long_rest","dice":"1d8+Intellect","save":null,"range":"30 ft","duration":null,"scaling":[],"scaling_rule":"Healing d8 every 5","status":"PROPOSED"}'::jsonb),
  ('script_of_ruin', 'Action: a bound creature within 60 feet takes 4d8 radiant (Judgment vs Intellect DC halves) and is knocked prone on a failure. Once per short rest.', 'action', '{"action_type":"action","uses":1,"recharge":"short_rest","dice":"4d8","save":{"stat":"Judgment","dc":"8 + proficiency bonus + Judgment"},"range":"60 ft","duration":null,"scaling":[],"key_stat":"Intellect","status":"PROPOSED"}'::jsonb),
