  ('temperance', 'Advantage on rolls against charm and possession. Once per short rest as a reaction, grant that advantage to an ally within 30 feet for one roll.', 'reaction', '{"action_type":"reaction","uses":1,"recharge":"short_rest","dice":null,"save":null,"range":"30 ft","duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('tempest_step', 'While furious, ignore difficult terrain; when you Dash, deal 1d6 lightning to one creature you pass within 5 feet of.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":"1d6","save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('thorned_fury', 'While furious, once per turn when you hit with melee, deal +1d6 and the target bleeds: 1d4 at the start of each of its turns until it regains HP or 1 minute passes.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":"1d6 + 1d4 bleed","save":null,"range":null,"duration":null,"scaling":[],"scaling_rule":"Brand d6 every 5","status":"PROPOSED"}'::jsonb),
  ('thorned_lullaby', 'Bonus action: a creature within 60 feet makes a Judgment roll vs Confidence DC or is charmed until the end of your next turn (hostile acts end it). Uses = proficiency bonus per long rest.', 'bonus', '{"action_type":"bonus","uses":"proficiency bonus","recharge":"long_rest","dice":null,"save":{"stat":"Judgment","dc":"8 + proficiency bonus + Judgment"},"range":"60 ft","duration":null,"scaling":[],"key_stat":"Confidence","status":"PROPOSED"}'::jsonb),
  ('thornheart', 'When a creature within 5 feet hits you with melee, it takes 1d8 piercing. You may use Judgment instead of Precision for opportunity attack rolls with melee spells or weapons you are proficient with.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":"1d8","save":null,"range":"5 ft","duration":null,"scaling":[],"scaling_rule":"Strike d8 every 4","status":"PROPOSED"}'::jsonb),
  ('thornking', 'Once per long rest as a bonus action while furious, for 1 minute your once-per-turn thorn damage becomes +2d8, bleed is 2d6, and Barbed Hide is 2d6.', 'bonus', '{"action_type":"bonus","uses":1,"recharge":"long_rest","dice":"2d8 / 2d6","save":null,"range":null,"duration":"1 minute","scaling":[],"status":"PROPOSED"}'::jsonb),
  ('thread_reading', 'Bonus action: learn a creature within 30 feet''s HP band (healthy/bloodied/critical) and whether it has daily auto-success rolls left. Uses = Judgment modifier (min 1) per long rest.', 'bonus', '{"action_type":"bonus","uses":"Judgment modifier (min 1)","recharge":"long_rest","dice":null,"save":null,"range":"30 ft","duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('throne_fire', 'Once per long rest as an action, for 1 minute Burning Wings is permanent, Holy Flame becomes 2d6, and Grace Bolt gains a 15-ft radius burst option (Speed vs Intellect DC; half on success) dealing Grace Bolt damage once.', 'action', '{"action_type":"action","uses":1,"recharge":"long_rest","dice":null,"save":{"stat":"Speed","dc":"8 + proficiency bonus + Speed"},"range":null,"duration":"1 minute","scaling":[],"key_stat":"Intellect","status":"PROPOSED"}'::jsonb),
  ('titan_stride', 'Giant''s Growth: +1d8 weapon damage, reach +5 ft stacks with size, and you may grow even if not furious once per long rest for 1 minute.', 'bonus', '{"action_type":"bonus","uses":null,"recharge":null,"dice":"+1d8","save":null,"range":null,"duration":"1 minute","scaling":[],"status":"PROPOSED"}'::jsonb),
  ('tower_ward', 'Action: gain temporary HP equal to 2d10 + Templar level and resistance to necrotic and radiant for 1 minute. Once per short rest.', 'action', '{"action_type":"action","uses":1,"recharge":"short_rest","dice":"2d10+Templar level","save":null,"range":null,"duration":"1 minute","scaling":[],"status":"PROPOSED"}'::jsonb),
  ('toxin_craft', 'During a long rest, prepare doses of toxin equal to proficiency bonus. Apply as a bonus action to a weapon for 1 minute. First hit deals 1d6 poison and Endurance vs Precision DC or poisoned until end of its next turn.', 'bonus', '{"action_type":"bonus","uses":"proficiency bonus doses","recharge":"long_rest","dice":"1d6","save":{"stat":"Endurance","dc":"8 + proficiency bonus + Endurance"},"range":null,"duration":"1 minute","scaling":[],"scaling_rule":"Brand d6 every 5","key_stat":"Precision","status":"PROPOSED"}'::jsonb),
  ('tracker', 'Advantage on Judgment and Precision checks to track, hunt, or recall lore about beasts and humanoids you have studied for 1 minute.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('tulips_bloom', 'When you restore HP with a Songsmith spell or feature, add 1d6. Once per turn grant the target +1 AC until the start of your next turn.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":"1d6","save":null,"range":null,"duration":null,"scaling":[],"scaling_rule":"Healing d4 every 3","status":"PROPOSED"}'::jsonb),
  ('twin_conjuring', 'Once per long rest when you cast a conjuration that summons one creature, summon two instead (shared duration; both vanish when the spell ends).', 'free', '{"action_type":"free","uses":1,"recharge":"long_rest","dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('twin_fang', 'When you hit with Coil''s attack, make one additional spear attack against the same target as part of that bonus action.', 'bonus', '{"action_type":"bonus","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('twin_pact', 'Once per short rest, the devil acts independently: as a reaction it makes one weapon attack using your bonuses when a creature within 5 feet attacks you.', 'reaction', '{"action_type":"reaction","uses":1,"recharge":"short_rest","dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('twin_runes', 'You may maintain two etched runes. Battle Scribe glyphs deal 3d6.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":"3d6","save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('twin_veil', 'You cast Celestial and Shade magic. After each long rest, choose Veil of Light or Veil of Shade: Light grants +1d4 to healing you restore; Shade grants +1d4 necrotic or psychic to one damage roll of each Priest spell you cast. Twin Veil(2) lets you switch as a bonus action once per short rest.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":"1d4","save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('twist_of_fate', 'Reaction: when you or an ally within 30 feet rolls a d20, add or subtract 1d4. Uses = proficiency bonus per long rest.', 'reaction', '{"action_type":"reaction","uses":"proficiency bonus","recharge":"long_rest","dice":"1d4","save":null,"range":"30 ft","duration":null,"scaling":[{"level":9,"change":"1d6"},{"level":15,"change":"1d8"}],"status":"PROPOSED"}'::jsonb),
  ('unarmored_toughness', 'While not wearing armor, AC = 10 + Precision + Endurance. You may use a shield.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('unbroken', 'While furious, if you would drop to 0 HP, make an Endurance roll DC 10 + damage taken beyond your HP; on success drop to 1 HP instead. DC increases by 5 each success until long rest; resets on long rest.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":{"stat":"Endurance","dc":"10 + overflow damage"},"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('unchained', 'Once per long rest as a bonus action, for 1 minute Grace Bolt targets up to six creatures within 60 feet (no clustering required), Siphon Grace heals Intellect + proficiency bonus, and you regain one short-rest slot at the start of each of your turns (max your slot total).', 'bonus', '{"action_type":"bonus","uses":1,"recharge":"long_rest","dice":null,"save":null,"range":"60 ft","duration":"1 minute","scaling":[],"status":"PROPOSED"}'::jsonb),
  ('undisputed', 'Unarmed die 2d8. When you roll initiative, regain all Drive (Flurry uses). Combo Chain stuns on two hits against the same target in a turn.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":"2d8","save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('undo', 'Reaction: when you or an ally within 30 feet takes damage, reduce it by 2d10 + Confidence. Once per short rest.', 'reaction', '{"action_type":"reaction","uses":1,"recharge":"short_rest","dice":"2d10+Confidence","save":null,"range":"30 ft","duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('undying_morrow', 'Once per long rest as an action, for 1 minute dying allies within 30 feet are stable at the start of their turns and regain 1 HP if still at 0 when they stabilize this way.', 'action', '{"action_type":"action","uses":1,"recharge":"long_rest","dice":null,"save":null,"range":"30 ft","duration":"1 minute","scaling":[],"status":"PROPOSED"}'::jsonb),
  ('unmaking', 'Once per long rest when you hit with a spell or Dark Strike, the target makes an Endurance roll vs Confidence DC; on a failure ongoing spells of 5th rank or lower on it end, and it takes +4d8 necrotic.', 'free', '{"action_type":"free","uses":1,"recharge":"long_rest","dice":"4d8","save":{"stat":"Endurance","dc":"8 + proficiency bonus + Endurance"},"range":null,"duration":null,"scaling":[],"key_stat":"Confidence","status":"PROPOSED"}'::jsonb),
  ('unshakable', 'Advantage on rolls against being frightened, restrained by mundane bonds, or moved against your will.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('untraceable', 'Advantage on rolls to avoid tracking, and magic that would locate you has disadvantage or requires a Judgment contest vs your Precision.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('unyielding', 'When you fail an Endurance or Might roll, you may succeed instead. Once per short rest.', 'free', '{"action_type":"free","uses":1,"recharge":"short_rest","dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('valor', 'When an ally within 30 feet hits your Challenge target, you may use your reaction to make one melee attack against it.', 'reaction', '{"action_type":"reaction","uses":null,"recharge":null,"dice":null,"save":null,"range":"30 ft","duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('vanish', 'Reaction when you take damage: become invisible until the start of your next turn or until you attack or cast. Once per short rest.', 'reaction', '{"action_type":"reaction","uses":1,"recharge":"short_rest","dice":null,"save":null,"range":null,"duration":"until start of next turn","scaling":[],"status":"PROPOSED"}'::jsonb),
  ('vanish_into_the_wild', 'You can Hide as a bonus action. In natural terrain, leaving no tracks and becoming invisible until you attack or cast while remaining still for 1 round (once per short rest).', 'bonus', '{"action_type":"bonus","uses":1,"recharge":"short_rest","dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('veilwalk', 'Bonus action: teleport up to 15 feet. Uses = proficiency bonus per long rest. Does not provoke.', 'bonus', '{"action_type":"bonus","uses":"proficiency bonus","recharge":"long_rest","dice":null,"save":null,"range":"15 ft","duration":null,"scaling":[{"level":9,"change":"30 feet"},{"level":15,"change":"60 feet"}],"status":"PROPOSED"}'::jsonb),
  ('vendetta', 'You may maintain two Grudge marks. Retaliate once per marked attacker per round.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('vengeful_shade', 'Bonus action: mark a creature within 60 feet for 1 minute. Your weapon attacks against it deal +1d6 necrotic, and it has disadvantage on attacks against creatures other than you while within 5 feet of you.', 'bonus', '{"action_type":"bonus","uses":null,"recharge":null,"dice":"1d6","save":null,"range":"60 ft","duration":"1 minute","scaling":[],"scaling_rule":"Brand d6 every 5","status":"PROPOSED"}'::jsonb),
  ('venom_fang', 'Once per turn when you hit, deal +1d4 poison and Endurance vs Precision DC or poisoned until end of its next turn.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":"1d4","save":{"stat":"Endurance","dc":"8 + proficiency bonus + Endurance"},"range":null,"duration":null,"scaling":[],"key_stat":"Precision","status":"PROPOSED"}'::jsonb),
  ('venom_strike', 'Hidden Blade may deal poison damage. When it does, target has disadvantage on Endurance rolls until the end of your next turn.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('verdant_grasp', 'Bonus action: vines restrain a creature within 30 feet (Might vs Judgment DC to avoid; repeats each turn) for 1 minute. Uses = Judgment modifier (min 1) per long rest.', 'bonus', '{"action_type":"bonus","uses":"Judgment modifier (min 1)","recharge":"long_rest","dice":null,"save":{"stat":"Might","dc":"8 + proficiency bonus + Might"},"range":"30 ft","duration":"1 minute","scaling":[{"level":8,"change":"Verdant Grasp(2): also deals 1d6 piercing at start of target turn; 2 targets if you expend two uses"}],"key_stat":"Judgment","status":"PROPOSED"}'::jsonb),
  ('verdict', 'Once per short rest when you hit your Bounty, it makes a Judgment roll vs Precision DC or is incapacitated until the end of its next turn and takes +2d8 damage.', 'free', '{"action_type":"free","uses":1,"recharge":"short_rest","dice":"2d8","save":{"stat":"Judgment","dc":"8 + proficiency bonus + Judgment"},"range":null,"duration":null,"scaling":[],"key_stat":"Precision","status":"PROPOSED"}'::jsonb),
  ('verse', 'Bonus action: begin a Verse lasting 1 minute (you must be able to speak). Choose Courage (+1d4 to allies'' attack rolls within 30 feet) or Dissonance (enemies within 30 feet subtract 1d4 from their first attack each turn). Uses = Confidence modifier (min 1) per long rest. Verse(2)/(3) improve.', 'bonus', '{"action_type":"bonus","uses":"Confidence modifier (min 1)","recharge":"long_rest","dice":"1d4","save":null,"range":"30 ft","duration":"1 minute","scaling":[{"level":5,"change":"Verse(2): die 1d6; one extra use"},{"level":14,"change":"Verse(3): die 1d8; allies also gain temporary HP equal to Confidence when Verse starts"}],"status":"PROPOSED"}'::jsonb),
  ('vipers_tears', 'Once per long rest as a bonus action, for 1 minute Venom Fang becomes 2d6 poison and a failed Endurance roll also incapacitates until the end of the target''s next turn; Coil does not require staying still.', 'bonus', '{"action_type":"bonus","uses":1,"recharge":"long_rest","dice":"2d6","save":{"stat":"Endurance","dc":"8 + proficiency bonus + Endurance"},"range":null,"duration":"1 minute","scaling":[],"key_stat":"Precision","status":"PROPOSED"}'::jsonb),
  ('virtues_mend', 'Learn Virtue Invocations. Bonus action: touch a creature to restore 1d8 + Intellect HP. Uses = Intellect modifier (min 1) per long rest.', 'bonus', '{"action_type":"bonus","uses":"Intellect modifier (min 1)","recharge":"long_rest","dice":"1d8+Intellect","save":null,"range":"touch","duration":null,"scaling":[],"scaling_rule":"Healing d8 every 5","status":"PROPOSED"}'::jsonb),
  ('virulent_dose', 'Toxin damage becomes 2d6 and poisoned lasts 1 minute (repeats Endurance at end of turns).', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":"2d6","save":null,"range":null,"duration":"1 minute","scaling":[],"status":"PROPOSED"}'::jsonb),
  ('vital_strike', 'When you crit with unarmed, deal +3d8 and the target makes an Endurance roll vs Precision DC or is stunned until the end of your next turn.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":"3d8","save":{"stat":"Endurance","dc":"8 + proficiency bonus + Endurance"},"range":null,"duration":null,"scaling":[],"key_stat":"Precision","status":"PROPOSED"}'::jsonb),
  ('voice_of_the_void', 'Once per long rest as an action, each enemy within 30 feet makes a Judgment roll vs Judgment DC or is frightened for 1 minute and takes 4d8 psychic; repeats each turn. On success, half damage and no fear.', 'action', '{"action_type":"action","uses":1,"recharge":"long_rest","dice":"4d8","save":{"stat":"Judgment","dc":"8 + proficiency bonus + Judgment"},"range":"30 ft","duration":"1 minute","scaling":[],"key_stat":"Judgment","status":"PROPOSED"}'::jsonb),
  ('voice_of_the_wild', 'You may maintain concentration-equivalent on two Seer spells at once (if either would break, choose which ends). Once per long rest, cast a Seer spell of 5th rank or lower without a slot.', 'passive', '{"action_type":"passive","uses":1,"recharge":"long_rest","dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('volley', 'Action: make a ranged attack against any number of creatures within 10 feet of a point you choose within range (separate rolls; one attack each). Once per short rest.', 'action', '{"action_type":"action","uses":1,"recharge":"short_rest","dice":null,"save":null,"range":"weapon","duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('waking_dream', 'Once per long rest as an action, for 1 minute create three illusory duplicates (as a mirror image effect with 3 images) and your Dream Step has unlimited uses during that minute.', 'action', '{"action_type":"action","uses":1,"recharge":"long_rest","dice":null,"save":null,"range":null,"duration":"1 minute","scaling":[],"status":"PROPOSED"}'::jsonb),
  ('war_hymn', 'Verse of Courage also adds +1d4 to allies'' damage rolls.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":"1d4","save":null,"range":null,"duration":null,"scaling":[],"scaling_rule":"Brand d6 every 5","status":"PROPOSED"}'::jsonb),
  ('warbringer', 'Might and Endurance scores increase by 4 (respecting caps). While furious, speed +10 feet and Reckless Swing no longer grants advantage on attacks against you.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb)
) AS v(feature_key, description, type, rules)
WHERE f.key = v.feature_key;

UPDATE features f SET
  description = v.description,
  type = v.type,
  data = COALESCE(f.data, '{}'::jsonb) || v.rules
FROM (VALUES
  ('warded_circle', 'Action: 15-ft-radius circle for 1 minute. Chosen creatures cannot leave or enter without succeeding on a Judgment roll vs your Judgment DC. Once per short rest.', 'action', '{"action_type":"action","uses":1,"recharge":"short_rest","dice":null,"save":{"stat":"Judgment","dc":"8 + proficiency bonus + Judgment"},"range":"15 ft","duration":"1 minute","scaling":[],"key_stat":"Judgment","status":"PROPOSED"}'::jsonb),
  ('warding_trap', 'Action: set a trap in a 5-ft space (1 minute to hide it). First enemy to enter takes 2d8 damage (type chosen) and Speed vs Precision DC or is restrained 1 minute. Uses = proficiency bonus per long rest.', 'action', '{"action_type":"action","uses":"proficiency bonus","recharge":"long_rest","dice":"2d8","save":{"stat":"Speed","dc":"8 + proficiency bonus + Speed"},"range":null,"duration":null,"scaling":[],"key_stat":"Precision","status":"PROPOSED"}'::jsonb),
  ('warm_refrain', 'Bonus action: one creature within 30 feet regains 1d8 + Confidence HP. Uses = proficiency bonus per long rest.', 'bonus', '{"action_type":"bonus","uses":"proficiency bonus","recharge":"long_rest","dice":"1d8+Confidence","save":null,"range":"30 ft","duration":null,"scaling":[],"scaling_rule":"Healing d8 every 5","status":"PROPOSED"}'::jsonb),
  ('weak_point', 'Bonus action: analyze a creature within 30 feet; until the end of your next turn your unarmed attacks against it ignore 2 AC from armor/shield and deal +1d4.', 'bonus', '{"action_type":"bonus","uses":null,"recharge":null,"dice":"1d4","save":null,"range":"30 ft","duration":"until end of next turn","scaling":[],"scaling_rule":"Strike d6 every 4","status":"PROPOSED"}'::jsonb),
  ('web_line', 'Bonus action: create a 30-ft line of silk between two points or to a surface; it is difficult terrain for enemies and can be climbed by you without checks. Uses = proficiency bonus per long rest. Lasts 1 minute.', 'bonus', '{"action_type":"bonus","uses":"proficiency bonus","recharge":"long_rest","dice":null,"save":null,"range":"30 ft","duration":"1 minute","scaling":[],"status":"PROPOSED"}'::jsonb),
  ('web_of_lies', 'Once per long rest as an action, fill a 30-ft cube within 60 feet with silk for 1 minute: enemies treat it as difficult terrain, are lightly obscured to others, and at the start of their turns make Speed vs Precision DC or are restrained until they escape.', 'action', '{"action_type":"action","uses":1,"recharge":"long_rest","dice":null,"save":{"stat":"Speed","dc":"8 + proficiency bonus + Speed"},"range":"60 ft","duration":"1 minute","scaling":[],"key_stat":"Precision","status":"PROPOSED"}'::jsonb),
  ('whirlwind', 'Action: one melee attack with a reach weapon against each creature of your choice within reach. Once per short rest.', 'action', '{"action_type":"action","uses":1,"recharge":"short_rest","dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('wild_sovereign', 'Once per long rest as an action, for 1 minute your companion grows one size, gains +2 AC and Extra Attack, and Pack Hunt triggers on every hit against your Bounty.', 'action', '{"action_type":"action","uses":1,"recharge":"long_rest","dice":null,"save":null,"range":null,"duration":"1 minute","scaling":[],"status":"PROPOSED"}'::jsonb),
  ('wild_tongue', 'You can speak with beasts and plants. Judgment checks to influence them have advantage. Wild Tongue(2) extends to elementals of nature.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('willow_ward', 'Reaction: when an ally within 30 feet is hit, grant them resistance to that damage. Uses = proficiency bonus per long rest.', 'reaction', '{"action_type":"reaction","uses":"proficiency bonus","recharge":"long_rest","dice":null,"save":null,"range":"30 ft","duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('willows_shelter', 'When you heal with Grace or a Templar spell, the target also gains temporary HP equal to your Judgment modifier (min 1).', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":"Judgment modifier","save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('wilting_note', 'Cantrip-like action: one creature within 60 feet takes 2d6 necrotic (Judgment vs Confidence DC halves). Scales Cantrip d6-equivalent as Burst. Uses at will.', 'action', '{"action_type":"action","uses":null,"recharge":null,"dice":"2d6","save":{"stat":"Judgment","dc":"8 + proficiency bonus + Judgment"},"range":"60 ft","duration":null,"scaling":[],"scaling_rule":"Cantrip d8","key_stat":"Confidence","status":"PROPOSED"}'::jsonb),
  ('withering_touch', 'Melee spell attacks and touch cantrips deal +1d6 necrotic; hit target has disadvantage on Might rolls until the end of your next turn.', 'passive', '{"action_type":"passive","uses":null,"recharge":null,"dice":"1d6","save":null,"range":null,"duration":null,"scaling":[],"scaling_rule":"Brand d6 every 5","status":"PROPOSED"}'::jsonb),
  ('worldroot', 'Action: teleport up to 60 feet to a space with plant life or soft earth you have seen. Uses = proficiency bonus per long rest.', 'action', '{"action_type":"action","uses":"proficiency bonus","recharge":"long_rest","dice":null,"save":null,"range":"60 ft","duration":null,"scaling":[],"status":"PROPOSED"}'::jsonb),
  ('wrath_of_the_reeds', 'Once per long rest as an action while furious, for 1 minute your melee lightning becomes +2d6, bolt becomes 3d8, and Living Storm is 2d6.', 'action', '{"action_type":"action","uses":1,"recharge":"long_rest","dice":"2d6 / 3d8","save":null,"range":null,"duration":"1 minute","scaling":[],"status":"PROPOSED"}'::jsonb),
  ('wrath_unbound', 'Once per long rest, when a Grudge target drops you below half HP, your next Attack action against it before the end of your next turn crits on 18-20 and adds 3d8 per hit.', 'free', '{"action_type":"free","uses":1,"recharge":"long_rest","dice":"3d8","save":null,"range":null,"duration":"until end of next turn","scaling":[],"status":"PROPOSED"}'::jsonb)
) AS v(feature_key, description, type, rules)
WHERE f.key = v.feature_key;

-- Merge per-level rules into role_features.data (keep slot_table/cantrips)
UPDATE role_features rf SET
  rank = v.rank,
  data = COALESCE(rf.data, '{}'::jsonb) || v.rules
FROM (VALUES
  ('warrior', 'preferred_arms', 1, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[{"level":10,"change":"bonus becomes +2"}],"status":"PROPOSED","description":"Choose two weapon groups. While wielding a Preferred Arms weapon, add +1 to attack rolls. At level 10 the bonus becomes +2."}'::jsonb),
  ('warrior', 'draw_breath', 1, 1, '{"action_type":"bonus","uses":1,"recharge":"short_rest","dice":"1d10+Warrior level","save":null,"range":"self","duration":"instant","scaling":[],"status":"PROPOSED","description":"As a bonus action, regain hit points equal to 1d10 + your Warrior level. 1 use, recharges on a short or long rest."}'::jsonb),
