  ('reaver', 'soul_harvest', 1, 1, '{"action_type":"bonus","uses":"Souls max PB","recharge":null,"dice":"1d8+Confidence","save":null,"range":null,"duration":null,"scaling":[{"level":8,"change":"Soul Harvest(2): spend 1 Soul for +1d6 on a hit; or 2 Souls to regain 2d8+Confidence"}],"status":"PROPOSED","description":"When you reduce a creature to 0 HP, gain 1 Soul (max = proficiency bonus). Bonus action: spend 1 Soul to regain 1d8 + Confidence HP. Soul Harvest(2) improves spending options."}'::jsonb),
  ('reaver', 'dark_strike', 1, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":"1d6","save":null,"range":null,"duration":null,"scaling":[{"level":5,"change":"+1d6"},{"level":10,"change":"+1d6"},{"level":15,"change":"+1d6"},{"level":20,"change":"+1d6"}],"scaling_rule":"Brand d6 every 5","status":"PROPOSED","description":"Once per turn when you hit with a melee weapon, deal +1d6 necrotic. Scales Brand d6 every 5."}'::jsonb),
  ('reaver', 'spellcraft', 2, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"casting_stat":"Confidence","spell_table":2,"status":"PROPOSED","slot_table":2,"description":"You cast spells using the half-caster slot table for your role level. Spell attack and spell DC use 8 + proficiency bonus + your casting stat. Casting stat: Confidence."}'::jsonb),
  ('reaver', 'dread_aura', 2, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":{"stat":"Judgment","dc":"8 + proficiency bonus + Judgment"},"range":"10 ft","duration":null,"scaling":[],"key_stat":"Confidence","status":"PROPOSED","description":"Aura 10 feet: enemies that start their turn there make a Judgment roll vs Confidence DC or have disadvantage on their next attack before the start of your next turn. Soft once-per-creature-per-minute. Dread Aura(2) expands."}'::jsonb),
  ('reaver', 'extra_attack', 5, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"attacks":2,"extra_attacks":1,"status":"PROPOSED","description":"When you take the Attack action on your turn, you may make 1 extra attack (twice total)."}'::jsonb),
  ('reaver', 'soul_harvest', 8, 2, '{"action_type":"bonus","uses":null,"recharge":null,"dice":"1d6 / 2d8+Confidence","save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED","description":"Spend 1 Soul when you hit to deal +1d6 necrotic, or 2 Souls as a bonus action to regain 2d8 + Confidence HP."}'::jsonb),
  ('reaver', 'life_drain', 8, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED","description":"When Dark Strike damages a creature, you regain HP equal to half the Dark Strike bonus dice (rounded up)."}'::jsonb),
  ('reaver', 'reap', 11, 1, '{"action_type":"action","uses":1,"recharge":"short_rest","dice":null,"save":null,"range":"5 ft","duration":null,"scaling":[],"status":"PROPOSED","description":"Action: melee attack against each creature within 5 feet. Separate rolls. Once per short rest."}'::jsonb),
  ('reaver', 'dread_aura', 14, 2, '{"action_type":"passive","uses":null,"recharge":null,"dice":"1d6","save":{"stat":"Judgment","dc":"8 + proficiency bonus + Judgment"},"range":"30 ft","duration":null,"scaling":[],"key_stat":"Confidence","status":"PROPOSED","description":"Aura becomes 30 feet. Failed Judgment also deals 1d6 psychic."}'::jsonb),
  ('reaver', 'soul_furnace', 17, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED","description":"At the start of combat, gain 2 Souls. Max Souls becomes proficiency bonus + 2."}'::jsonb),
  ('reaver', 'harbinger', 20, 1, '{"action_type":"bonus","uses":1,"recharge":"long_rest","dice":"3d6","save":null,"range":null,"duration":"1 minute","scaling":[],"status":"PROPOSED","description":"Once per long rest as a bonus action, for 1 minute Dark Strike becomes +3d6, Dread Aura auto-applies disadvantage without a roll once per creature turn, and reducing a creature to 0 HP grants 2 Souls."}'::jsonb),
  ('knight', 'oath_of_steel', 1, 1, '{"action_type":"bonus","uses":null,"recharge":null,"dice":"1d4 AC to ally","save":null,"range":"5 ft","duration":"until start of next turn","scaling":[],"status":"PROPOSED","description":"You are proficient with heavy armor, shields, and martial weapons. As a bonus action, adopt a Guard: +1 AC until the start of your next turn, or +1d4 to one ally''s AC within 5 feet until the start of your next turn."}'::jsonb),
  ('knight', 'heavy_training', 1, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED","description":"Ignore speed reduction from heavy armor. Climb and swim at full speed in heavy armor (still disadvantage on Stealth if armor imposes it)."}'::jsonb),
  ('knight', 'rally', 2, 1, '{"action_type":"bonus","uses":"proficiency bonus","recharge":"long_rest","dice":"1d8+Confidence","save":null,"range":"30 ft","duration":null,"scaling":[{"level":14,"change":"Rally(2): 2d8+Confidence; also end fear on affected allies"}],"scaling_rule":"Ward d10 every 5","status":"PROPOSED","description":"Bonus action: you and allies within 30 feet gain temporary HP equal to 1d8 + Confidence. Uses = proficiency bonus per long rest. Rally(2) improves."}'::jsonb),
  ('knight', 'extra_attack', 5, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"attacks":2,"extra_attacks":1,"status":"PROPOSED","description":"When you take the Attack action on your turn, you may make 1 extra attack (twice total)."}'::jsonb),
  ('knight', 'bulwark', 8, 1, '{"action_type":"reaction","uses":"proficiency bonus","recharge":"long_rest","dice":null,"save":null,"range":"5 ft","duration":null,"scaling":[],"status":"PROPOSED","description":"While wielding a shield, +1 AC. Reaction: impose disadvantage on an attack against an ally within 5 feet. Uses = proficiency bonus per long rest."}'::jsonb),
  ('knight', 'extra_attack', 11, 2, '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"attacks":3,"extra_attacks":2,"status":"PROPOSED","description":"When you take the Attack action on your turn, you may make 2 extra attacks (three times total)."}'::jsonb),
  ('knight', 'rally', 14, 2, '{"action_type":"bonus","uses":null,"recharge":null,"dice":"2d8+Confidence","save":null,"range":"30 ft","duration":null,"scaling":[],"status":"PROPOSED","description":"Rally grants 2d8 + Confidence temporary HP and ends the frightened condition on affected allies."}'::jsonb),
  ('knight', 'unyielding', 17, 1, '{"action_type":"free","uses":1,"recharge":"short_rest","dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED","description":"When you fail an Endurance or Might roll, you may succeed instead. Once per short rest."}'::jsonb)
) AS v(role_key, feature_key, level, rank, rules)
JOIN roles r ON r.key = v.role_key
JOIN features f ON f.key = v.feature_key
WHERE rf.role_id = r.id AND rf.feature_id = f.id AND rf.level = v.level;

UPDATE role_features rf SET
  rank = v.rank,
  data = COALESCE(rf.data, '{}'::jsonb) || v.rules
FROM (VALUES
  ('knight', 'paragon', 20, 1, '{"action_type":"bonus","uses":1,"recharge":"long_rest","dice":null,"save":null,"range":null,"duration":"1 minute","scaling":[],"status":"PROPOSED","description":"Once per long rest as a bonus action, for 1 minute gain +2 AC, Rally does not expend uses, and Bulwark reactions do not expend uses."}'::jsonb),
  ('lancer', 'reach_mastery', 1, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":"+5 ft reach","duration":null,"scaling":[],"status":"PROPOSED","description":"Spears, lances, and polearms you wield have +5 feet reach if they did not already have reach, or +5 feet additional if they did (max 15 feet). Opportunity attacks with these weapons do not require a reaction when a creature enters your reach (once per turn free; further cost reaction)."}'::jsonb),
  ('lancer', 'spearwork', 1, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":"1d4","save":null,"range":null,"duration":null,"scaling":[{"level":5,"change":"1d6"},{"level":11,"change":"1d8"},{"level":17,"change":"1d10"}],"scaling_rule":"Strike d6 every 4","status":"PROPOSED","description":"You may use Precision for attack and damage with spears, lances, and polearms. Once per turn when you hit with such a weapon, deal +1d4."}'::jsonb),
  ('lancer', 'leap', 2, 1, '{"action_type":"bonus","uses":"proficiency bonus","recharge":"long_rest","dice":null,"save":null,"range":null,"duration":null,"scaling":[{"level":14,"change":"Leap(2): land adjacent to a creature and make one spear attack with advantage"}],"status":"PROPOSED","description":"Bonus action: jump horizontally up to your speed (or vertically half) without a running start; opportunity attacks against you during the leap have disadvantage. Uses = proficiency bonus per long rest. Leap(2) improves."}'::jsonb),
  ('lancer', 'extra_attack', 5, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"attacks":2,"extra_attacks":1,"status":"PROPOSED","description":"When you take the Attack action on your turn, you may make 1 extra attack (twice total)."}'::jsonb),
  ('lancer', 'impale', 8, 1, '{"action_type":"free","uses":1,"recharge":"short_rest","dice":null,"save":{"stat":"Might","dc":"8 + proficiency bonus + Might"},"range":null,"duration":null,"scaling":[],"key_stat":"Precision","status":"PROPOSED","description":"When you hit with a reach weapon, you may force a Might roll vs Precision DC; on a failure the target is restrained by the weapon until you withdraw it (bonus action) or they succeed on the roll at end of turn. While impaled, you cannot attack other targets with that weapon. Once per short rest."}'::jsonb),
  ('lancer', 'whirlwind', 11, 1, '{"action_type":"action","uses":1,"recharge":"short_rest","dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED","description":"Action: one melee attack with a reach weapon against each creature of your choice within reach. Once per short rest."}'::jsonb),
  ('lancer', 'leap', 14, 2, '{"action_type":"bonus","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED","description":"When you Leap, you may land within 5 feet of a creature and make one spear/polearm attack with advantage as part of the bonus action."}'::jsonb),
  ('lancer', 'skewer', 17, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":"2d8","save":{"stat":"Speed","dc":"8 + proficiency bonus + Speed"},"range":null,"duration":null,"scaling":[],"key_stat":"Precision","status":"PROPOSED","description":"Once per turn when you hit a creature that is Large or smaller with a reach weapon, deal +2d8 and push it 10 feet; Speed vs Precision DC negates the push."}'::jsonb),
  ('lancer', 'favor_of_the_monkey_king', 20, 1, '{"action_type":"bonus","uses":1,"recharge":"long_rest","dice":null,"save":null,"range":"60 ft","duration":"1 minute","scaling":[],"status":"PROPOSED","description":"Once per long rest as a bonus action, for 1 minute your spear strikes can target any creature you can see within 60 feet (the strike bridges the gap with golden reach). Attacks ignore half and three-quarters cover."}'::jsonb),
  ('songsmith', 'spellcraft', 1, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"casting_stat":"Confidence","spell_table":1,"status":"PROPOSED","slot_table":1,"description":"You cast spells using the full-caster slot table for your role level. Spell attack and spell DC use 8 + proficiency bonus + your casting stat. Casting stat: Confidence."}'::jsonb),
  ('songsmith', 'cantrips', 1, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"cantrips_known":2,"casting_stat":"Confidence","status":"PROPOSED","cantrips":2,"description":"You know 2 cantrips from your role''s lists. Cantrip damage follows Cantrip scaling rules."}'::jsonb),
  ('songsmith', 'verse', 1, 1, '{"action_type":"bonus","uses":"Confidence modifier (min 1)","recharge":"long_rest","dice":"1d4","save":null,"range":"30 ft","duration":"1 minute","scaling":[{"level":5,"change":"Verse(2): die 1d6; one extra use"},{"level":14,"change":"Verse(3): die 1d8; allies also gain temporary HP equal to Confidence when Verse starts"}],"status":"PROPOSED","description":"Bonus action: begin a Verse lasting 1 minute (you must be able to speak). Choose Courage (+1d4 to allies'' attack rolls within 30 feet) or Dissonance (enemies within 30 feet subtract 1d4 from their first attack each turn). Uses = Confidence modifier (min 1) per long rest. Verse(2)/(3) improve."}'::jsonb),
  ('songsmith', 'harmony', 2, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":"1d4 / half heal","save":null,"range":"15 ft","duration":null,"scaling":[],"status":"PROPOSED","description":"When you cast a Songsmith spell of 1st rank+ that targets an ally, another ally within 15 feet of them gains half the healing or +1d4 on their next attack before your next turn."}'::jsonb),
  ('songsmith', 'verse', 5, 2, '{"action_type":"bonus","uses":null,"recharge":null,"dice":"1d6","save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED","description":"Verse die becomes 1d6. Gain one additional Verse use."}'::jsonb),
  ('songsmith', 'countersong', 8, 1, '{"action_type":"reaction","uses":"proficiency bonus","recharge":"long_rest","dice":null,"save":null,"range":"60 ft","duration":null,"scaling":[],"status":"PROPOSED","description":"Reaction: when an ally within 60 feet fails a Judgment or Confidence roll against a charm/fear effect, add your Confidence modifier to the result. Uses = proficiency bonus per long rest."}'::jsonb),
  ('songsmith', 'encore', 11, 1, '{"action_type":"free","uses":1,"recharge":"short_rest","dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED","description":"When your Verse ends, you may immediately begin a different Verse without expending a use (once per short rest)."}'::jsonb),
  ('songsmith', 'verse', 14, 3, '{"action_type":"bonus","uses":null,"recharge":null,"dice":"1d8","save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED","description":"Verse die becomes 1d8. When you start a Verse, allies in range gain temporary HP equal to your Confidence modifier (min 1)."}'::jsonb),
  ('songsmith', 'crescendo', 17, 1, '{"action_type":"free","uses":1,"recharge":"long_rest","dice":"1d10","save":null,"range":null,"duration":"1 minute","scaling":[],"status":"PROPOSED","description":"Once per long rest when you cast a Songsmith spell of 1st rank+, treat it as one slot rank higher and Verse die becomes 1d10 for 1 minute."}'::jsonb),
  ('songsmith', 'magnum_opus', 20, 1, '{"action_type":"action","uses":1,"recharge":"long_rest","dice":null,"save":null,"range":"30 ft","duration":"1 minute","scaling":[],"status":"PROPOSED","description":"Once per long rest as an action, for 1 minute both Courage and Dissonance apply, Verse does not expend uses, and allies in range add your Confidence modifier to damage rolls."}'::jsonb),
  ('wraith', 'spellcraft', 1, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"casting_stat":"Intellect","spell_table":3,"status":"PROPOSED","slot_table":3,"description":"You cast using a short-rest slot table: few slots that return on a short or long rest. Spell attack and spell DC use 8 + proficiency bonus + your casting stat. Casting stat: Intellect."}'::jsonb),
  ('wraith', 'grace_bolt', 1, 1, '{"action_type":"action","uses":null,"recharge":null,"dice":"1d8 radiant + 1d4 fire","save":null,"range":"60 ft","duration":null,"scaling":[{"level":5,"change":"Grace Bolt(2): 2d8+1d4; up to 3 targets"},{"level":11,"change":"Grace Bolt(3): 3d8+1d4; up to 3 targets"},{"level":17,"change":"Grace Bolt(4): 4d8+1d4; up to 4 targets"}],"scaling_rule":"Cantrip d8","status":"PROPOSED","description":"Cantrip action: up to two creatures within 60 feet of you and within 10 feet of each other; ranged spell attack against each. On hit 1d8 radiant + 1d4 fire. Scales: extra target or die at Grace Bolt ranks. Cantrip d8 for the radiant die."}'::jsonb),
  ('wraith', 'radiant_invocations', 2, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[{"level":8,"change":"Radiant Invocations(2): learn two more; one may be greater"}],"status":"PROPOSED","description":"Learn two Radiant Invocations (Seal lists add more). Invocations modify Grace Bolt or grant at-will lesser miracles. You learn more at Radiant Invocations(2)."}'::jsonb),
  ('wraith', 'siphon_grace', 2, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":"Intellect modifier","save":null,"range":null,"duration":null,"scaling":[{"level":11,"change":"Siphon Grace(2): also gain temporary HP equal to number of Grace Bolt targets hit"}],"status":"PROPOSED","description":"When you hit with Grace Bolt, regain HP equal to your Intellect modifier (min 1) once per turn. Siphon Grace(2) improves."}'::jsonb),
  ('wraith', 'grace_bolt', 5, 2, '{"action_type":"action","uses":null,"recharge":null,"dice":"2d8+1d4","save":null,"range":"60 ft","duration":null,"scaling":[],"status":"PROPOSED","description":"Grace Bolt deals 2d8 radiant + 1d4 fire and can target up to three creatures (each within 10 feet of at least one other target)."}'::jsonb),
  ('wraith', 'radiant_invocations', 8, 2, '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED","description":"Learn two additional Radiant Invocations."}'::jsonb),
  ('wraith', 'grace_bolt', 11, 3, '{"action_type":"action","uses":null,"recharge":null,"dice":"3d8+1d4","save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED","description":"Grace Bolt deals 3d8 radiant + 1d4 fire (up to three targets)."}'::jsonb),
  ('wraith', 'siphon_grace', 11, 2, '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED","description":"When Grace Bolt hits, gain temporary HP equal to the number of targets hit in addition to Siphon healing."}'::jsonb),
  ('wraith', 'haloed', 14, 1, '{"action_type":"bonus","uses":1,"recharge":"short_rest","dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED","description":"You shed bright light 10 feet / dim 10 feet (suppressable). Advantage on Judgment rolls against fear and possession. Once per short rest as a bonus action, end one mild curse or poison on yourself."}'::jsonb),
  ('wraith', 'grace_bolt', 17, 4, '{"action_type":"action","uses":null,"recharge":null,"dice":"4d8+1d4","save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED","description":"Grace Bolt deals 4d8 radiant + 1d4 fire and can target up to four creatures."}'::jsonb),
  ('wraith', 'borrowed_miracle', 17, 1, '{"action_type":"action","uses":1,"recharge":"short_rest","dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED","description":"Once per short rest, cast a 1st- or 2nd-rank Wraith spell without expending a slot."}'::jsonb),
  ('wraith', 'unchained', 20, 1, '{"action_type":"bonus","uses":1,"recharge":"long_rest","dice":null,"save":null,"range":"60 ft","duration":"1 minute","scaling":[],"status":"PROPOSED","description":"Once per long rest as a bonus action, for 1 minute Grace Bolt targets up to six creatures within 60 feet (no clustering required), Siphon Grace heals Intellect + proficiency bonus, and you regain one short-rest slot at the start of each of your turns (max your slot total)."}'::jsonb)
) AS v(role_key, feature_key, level, rank, rules)
JOIN roles r ON r.key = v.role_key
JOIN features f ON f.key = v.feature_key
WHERE rf.role_id = r.id AND rf.feature_id = f.id AND rf.level = v.level;

-- Merge per-level rules into calling_features.data
UPDATE calling_features cf SET
  rank = v.rank,
  data = COALESCE(cf.data, '{}'::jsonb) || v.rules
FROM (VALUES
  ('path_of_the_reaper', 'reaping_swing', 3, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":"1d8","save":null,"range":null,"duration":null,"scaling":[{"level":8,"change":"+1d8"},{"level":13,"change":"+1d8"},{"level":18,"change":"+1d8"}],"scaling_rule":"Brand d8 every 5","status":"PROPOSED","description":"Once per turn when you hit with a melee weapon, deal an extra 1d8 damage. If the hit drops the target to 0 hit points, regain hit points equal to your Warrior level."}'::jsonb),
  ('path_of_the_reaper', 'harvest', 7, 1, '{"action_type":"bonus","uses":null,"recharge":null,"dice":null,"save":null,"range":"half speed","duration":null,"scaling":[],"status":"PROPOSED","description":"When you drop a creature to 0 hit points with a weapon attack, as a bonus action move up to half your speed and make one melee weapon attack against a different creature."}'::jsonb),
  ('path_of_the_reaper', 'grim_momentum', 9, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":"until end of next turn","scaling":[],"status":"PROPOSED","description":"After Harvest, your next weapon attack before the end of your next turn has advantage."}'::jsonb),
  ('path_of_the_reaper', 'scythe_arc', 13, 1, '{"action_type":"action","uses":1,"recharge":"short_rest","dice":null,"save":null,"range":"10 ft","duration":null,"scaling":[],"status":"PROPOSED","description":"As an action, make one melee attack against each creature of your choice within 10 feet. Once per short rest."}'::jsonb),
  ('path_of_the_reaper', 'deaths_cadence', 15, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED","description":"On a critical hit with a weapon, regain one spent Draw Breath use, or gain temporary hit points equal to Warrior level if none are spent."}'::jsonb),
  ('path_of_the_reaper', 'reapers_toll', 19, 1, '{"action_type":"free","uses":1,"recharge":"long_rest","dice":"10d10","save":{"stat":"Endurance","dc":"8 + proficiency bonus + Endurance"},"range":null,"duration":null,"scaling":[],"key_stat":"Might","status":"PROPOSED","description":"Once per long rest when you hit with a melee weapon, the target makes an Endurance roll vs Might DC; on a failure it drops to 0 if it has 100 HP or fewer, otherwise (or on success) it takes 10d10 necrotic."}'::jsonb),
  ('path_of_revenge', 'grudge', 3, 1, '{"action_type":"bonus","uses":null,"recharge":null,"dice":"1d6","save":null,"range":"60 ft","duration":"1 minute","scaling":[{"level":8,"change":"+1d6"},{"level":13,"change":"+1d6"},{"level":18,"change":"+1d6"}],"scaling_rule":"Brand d6 every 5","status":"PROPOSED","description":"Bonus action: mark a creature within 60 feet for 1 minute. Add 1d6 damage on weapon attacks against it. One mark; replacing ends the old. Scales Brand d6 every 5."}'::jsonb),
  ('path_of_revenge', 'retaliate', 7, 1, '{"action_type":"reaction","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED","description":"When your Grudge target hits you, reaction: one weapon attack against it."}'::jsonb),
  ('path_of_revenge', 'blood_debt', 9, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":"PB necrotic","save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED","description":"While Grudge is active, the first time each turn the marked creature damages you, it takes necrotic damage equal to your proficiency bonus."}'::jsonb),
  ('path_of_revenge', 'spite', 13, 1, '{"action_type":"free","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED","description":"When you hit your Grudge target, you may forgo Grudge bonus damage to impose disadvantage on its next attack roll before the end of its next turn."}'::jsonb),
  ('path_of_revenge', 'vendetta', 15, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED","description":"You may maintain two Grudge marks. Retaliate once per marked attacker per round."}'::jsonb),
  ('path_of_revenge', 'wrath_unbound', 19, 1, '{"action_type":"free","uses":1,"recharge":"long_rest","dice":"3d8","save":null,"range":null,"duration":"until end of next turn","scaling":[],"status":"PROPOSED","description":"Once per long rest, when a Grudge target drops you below half HP, your next Attack action against it before the end of your next turn crits on 18-20 and adds 3d8 per hit."}'::jsonb),
