  ('tome_of_dreaming', 'dream_step', 3, 1, '{"action_type":"bonus","uses":"proficiency bonus","recharge":"long_rest","dice":null,"save":null,"range":"15 ft","duration":null,"scaling":[{"level":9,"change":"30 feet"},{"level":15,"change":"60 feet"}],"status":"PROPOSED","description":"Bonus action: teleport up to 15 feet to a space you can see. Uses = proficiency bonus per long rest. Does not provoke."}'::jsonb),
  ('tome_of_dreaming', 'dream_slot', 7, 1, '{"action_type":"passive","uses":1,"recharge":"long_rest","dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED","description":"After a long rest, choose one prepared Mage spell of 1st or 2nd rank; you may cast it once without a slot before your next long rest."}'::jsonb)
) AS v(calling_key, feature_key, level, rank, rules)
JOIN callings c ON c.key = v.calling_key
JOIN features f ON f.key = v.feature_key
WHERE cf.calling_id = c.id AND cf.feature_id = f.id AND cf.level = v.level;

UPDATE calling_features cf SET
  rank = v.rank,
