  ('ballad_of_the_black_rose', 'thorned_lullaby', 3, 1, '{"action_type":"bonus","uses":"proficiency bonus","recharge":"long_rest","dice":null,"save":{"stat":"Judgment","dc":"8 + proficiency bonus + Judgment"},"range":"60 ft","duration":null,"scaling":[],"key_stat":"Confidence","status":"PROPOSED","description":"Bonus action: a creature within 60 feet makes a Judgment roll vs Confidence DC or is charmed until the end of your next turn (hostile acts end it). Uses = proficiency bonus per long rest."}'::jsonb),
  ('ballad_of_the_black_rose', 'dirge', 7, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED","description":"Verse of Dissonance: enemies also have disadvantage on Judgment rolls while in the aura."}'::jsonb),
  ('ballad_of_the_black_rose', 'wilting_note', 9, 1, '{"action_type":"action","uses":null,"recharge":null,"dice":"2d6","save":{"stat":"Judgment","dc":"8 + proficiency bonus + Judgment"},"range":"60 ft","duration":null,"scaling":[],"scaling_rule":"Cantrip d8","key_stat":"Confidence","status":"PROPOSED","description":"Cantrip-like action: one creature within 60 feet takes 2d6 necrotic (Judgment vs Confidence DC halves). Scales Cantrip d6-equivalent as Burst. Uses at will."}'::jsonb),
  ('ballad_of_the_black_rose', 'requiem', 13, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":"1d8","save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED","description":"When a creature charmed by you takes damage from your spells, it takes +1d8 psychic and the charm does not auto-end from that damage (still ends on other allies harming it)."}'::jsonb),
  ('ballad_of_the_black_rose', 'mourning_song', 15, 1, '{"action_type":"action","uses":1,"recharge":"short_rest","dice":null,"save":{"stat":"Judgment","dc":"8 + proficiency bonus + Judgment"},"range":"30 ft","duration":"1 minute","scaling":[],"key_stat":"Confidence","status":"PROPOSED","description":"Action: enemies within 30 feet make Judgment vs Confidence DC or are frightened for 1 minute (repeat each turn). Once per short rest."}'::jsonb),
  ('ballad_of_the_black_rose', 'black_rose_elegy', 19, 1, '{"action_type":"action","uses":1,"recharge":"long_rest","dice":"4d6 / 2d6","save":null,"range":null,"duration":"1 minute","scaling":[],"status":"PROPOSED","description":"Once per long rest as an action, for 1 minute Thorned Lullaby auto-succeeds once per turn (still costs bonus action), Wilting Note deals 4d6, and frightened enemies take 2d6 psychic at the start of their turns."}'::jsonb),
  ('seal_of_the_nephilim', 'enochian_binding', 3, 1, '{"action_type":"bonus","uses":"Intellect modifier (min 1)","recharge":"long_rest","dice":null,"save":null,"range":"30 ft","duration":"1 minute","scaling":[],"status":"PROPOSED","description":"Learn the Nephilim Invocation list. Bonus action: bind a creature within 30 feet for 1 minute; it has disadvantage on attacks against creatures other than you. Uses = Intellect modifier (min 1) per long rest."}'::jsonb),
  ('seal_of_the_nephilim', 'grace_edged', 7, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":"1d4","save":null,"range":null,"duration":null,"scaling":[],"scaling_rule":"Brand d6 every 5","status":"PROPOSED","description":"Your melee weapon attacks deal +1d4 radiant. You may use Intellect for attack and damage with simple melee weapons."}'::jsonb),
  ('seal_of_the_nephilim', 'extra_attack', 9, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":null,"save":null,"range":null,"duration":null,"scaling":[],"attacks":2,"extra_attacks":1,"status":"PROPOSED","description":"When you take the Attack action on your turn, you may make 1 extra attack (twice total)."}'::jsonb),
  ('seal_of_the_nephilim', 'seal_strike', 13, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":"2d6","save":null,"range":"10 ft pull","duration":null,"scaling":[],"status":"PROPOSED","description":"Once per turn when you hit a bound creature with a weapon or Grace Bolt, deal +2d6 radiant and pull it up to 10 feet toward you."}'::jsonb),
  ('seal_of_the_nephilim', 'script_of_ruin', 15, 1, '{"action_type":"action","uses":1,"recharge":"short_rest","dice":"4d8","save":{"stat":"Judgment","dc":"8 + proficiency bonus + Judgment"},"range":"60 ft","duration":null,"scaling":[],"key_stat":"Intellect","status":"PROPOSED","description":"Action: a bound creature within 60 feet takes 4d8 radiant (Judgment vs Intellect DC halves) and is knocked prone on a failure. Once per short rest."}'::jsonb),
  ('seal_of_the_nephilim', 'nephil_ascendant', 19, 1, '{"action_type":"bonus","uses":1,"recharge":"long_rest","dice":"2d6","save":null,"range":null,"duration":"1 minute","scaling":[],"attacks":3,"extra_attacks":2,"status":"PROPOSED","description":"Once per long rest as a bonus action, for 1 minute you fight as if you had Extra Attack(2) (2 extra attacks, 3 total), Grace-Edged becomes +2d6, and Enochian Binding does not expend uses."}'::jsonb),
  ('seal_of_the_seraphim', 'burning_wings', 3, 1, '{"action_type":"bonus","uses":"proficiency bonus","recharge":"long_rest","dice":null,"save":null,"range":"fly 30","duration":"1 minute","scaling":[],"status":"PROPOSED","description":"Learn Seraphim Invocations. Bonus action: for 1 minute gain fly speed 30 feet (hover). Uses = proficiency bonus per long rest. While flying, Grace Bolt fire die becomes 1d6."}'::jsonb),
  ('seal_of_the_seraphim', 'holy_flame', 7, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":"1d6","save":null,"range":null,"duration":null,"scaling":[],"scaling_rule":"Ongoing d6 every 5","status":"PROPOSED","description":"When Grace Bolt hits, the target takes +1d6 fire at the start of its next turn unless it spends its action to extinguish (no roll)."}'::jsonb),
  ('seal_of_the_seraphim', 'empowered_bolt', 9, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":"Intellect","save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED","description":"Once per turn, add Intellect modifier again as radiant damage to one Grace Bolt hit."}'::jsonb),
  ('seal_of_the_seraphim', 'seraphs_gaze', 13, 1, '{"action_type":"action","uses":1,"recharge":"short_rest","dice":null,"save":{"stat":"Judgment","dc":"8 + proficiency bonus + Judgment"},"range":"30 ft cone","duration":null,"scaling":[],"key_stat":"Intellect","status":"PROPOSED","description":"Action: creatures of your choice within a 30-ft cone make a Judgment roll vs Intellect DC or are blinded until the end of their next turn. Once per short rest."}'::jsonb),
  ('seal_of_the_seraphim', 'sixfold_fire', 15, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":"2d6","save":null,"range":null,"duration":null,"scaling":[],"status":"PROPOSED","description":"Grace Bolt may deal all fire or all radiant. When you hit three or more targets, deal +2d6 fire to each."}'::jsonb),
  ('seal_of_the_seraphim', 'throne_fire', 19, 1, '{"action_type":"action","uses":1,"recharge":"long_rest","dice":null,"save":{"stat":"Speed","dc":"8 + proficiency bonus + Speed"},"range":null,"duration":"1 minute","scaling":[],"key_stat":"Intellect","status":"PROPOSED","description":"Once per long rest as an action, for 1 minute Burning Wings is permanent, Holy Flame becomes 2d6, and Grace Bolt gains a 15-ft radius burst option (Speed vs Intellect DC; half on success) dealing Grace Bolt damage once."}'::jsonb),
  ('seal_of_the_virtue', 'virtues_mend', 3, 1, '{"action_type":"bonus","uses":"Intellect modifier (min 1)","recharge":"long_rest","dice":"1d8+Intellect","save":null,"range":"touch","duration":null,"scaling":[],"scaling_rule":"Healing d8 every 5","status":"PROPOSED","description":"Learn Virtue Invocations. Bonus action: touch a creature to restore 1d8 + Intellect HP. Uses = Intellect modifier (min 1) per long rest."}'::jsonb),
  ('seal_of_the_virtue', 'shared_grace', 7, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":"Intellect","save":null,"range":"30 ft","duration":null,"scaling":[],"status":"PROPOSED","description":"When Siphon Grace heals you, an ally within 30 feet also regains HP equal to your Intellect modifier (min 1)."}'::jsonb),
  ('seal_of_the_virtue', 'temperance', 9, 1, '{"action_type":"reaction","uses":1,"recharge":"short_rest","dice":null,"save":null,"range":"30 ft","duration":null,"scaling":[],"status":"PROPOSED","description":"Advantage on rolls against charm and possession. Once per short rest as a reaction, grant that advantage to an ally within 30 feet for one roll."}'::jsonb),
  ('seal_of_the_virtue', 'fortitude', 13, 1, '{"action_type":"passive","uses":null,"recharge":null,"dice":"Wraith level","save":null,"range":"30 ft","duration":null,"scaling":[],"status":"PROPOSED","description":"When you finish a short rest, you and allies within 30 feet gain temporary HP equal to your Wraith level."}'::jsonb),
  ('seal_of_the_virtue', 'charity', 15, 1, '{"action_type":"action","uses":1,"recharge":"short_rest","dice":"2d8+Intellect","save":null,"range":"30 ft","duration":null,"scaling":[],"status":"PROPOSED","description":"Action: transfer any number of your temporary HP to allies within 30 feet, or spend a short-rest slot to heal all allies within 30 feet for 2d8 + Intellect. Once per short rest for the slot heal."}'::jsonb),
  ('seal_of_the_virtue', 'perfect_virtue', 19, 1, '{"action_type":"action","uses":1,"recharge":"long_rest","dice":null,"save":null,"range":"30 ft","duration":"1 minute","scaling":[],"status":"PROPOSED","description":"Once per long rest as an action, for 1 minute Virtue''s Mend does not expend uses, Shared Grace heals twice Intellect, and allies within 30 feet have resistance to necrotic and psychic."}'::jsonb)
) AS v(calling_key, feature_key, level, rank, rules)
JOIN callings c ON c.key = v.calling_key
JOIN features f ON f.key = v.feature_key
WHERE cf.calling_id = c.id AND cf.feature_id = f.id AND cf.level = v.level;

-- Diagnostics
SELECT 'scaling_rules' AS what, count(*)::text AS n FROM scaling_rules
UNION ALL
SELECT 'features_with_description', count(*)::text FROM features WHERE description IS NOT NULL AND description <> ''
UNION ALL
SELECT 'features_with_rules_status', count(*)::text FROM features WHERE data ? 'status'
UNION ALL
SELECT 'role_features_with_action_type', count(*)::text FROM role_features WHERE data ? 'action_type'
UNION ALL
SELECT 'calling_features_with_action_type', count(*)::text FROM calling_features WHERE data ? 'action_type';

