SELECT w.calling_key, w.feature_key, w.level
FROM wanted w
LEFT JOIN callings c ON c.key = w.calling_key
LEFT JOIN features f ON f.key = w.feature_key
LEFT JOIN calling_features cf ON cf.calling_id = c.id AND cf.feature_id = f.id AND cf.level = w.level
WHERE cf.calling_id IS NULL
ORDER BY 1,2,3;

